from fractions import Fraction

def get_neighbors(r):
    neighbors = []
    # r + r' = 0 => r' = -r
    r_prime = -r
    if r_prime != r:
        neighbors.append(r_prime)
    # r + r' = 1 => r' = 1 - r
    r_prime = 1 - r
    if r_prime != r:
        neighbors.append(r_prime)
    # r * r' = 1 => r' = 1/r
    if r != 0:
        r_prime = 1/r
        if r_prime != r:
            neighbors.append(r_prime)
    return neighbors

