def find_path_parity(start, target):
    queue = [(start, 0)]
    visited = {start: 0}
    while queue:
        curr, dist = queue.pop(0)
        if curr == target:
            return dist % 2
        for neighbor in get_neighbors(curr):
            if neighbor not in visited:
                visited[neighbor] = dist + 1
                queue.append((neighbor, dist + 1))
    return None

