def solve():
    start_x = Fraction(2, 3)
    targets = [Fraction(1, 3), Fraction(3, 4), Fraction(4, 5), Fraction(10, 11), Fraction(3, 71), Fraction(5, 204)]

    queue = deque([(start_x, 0)])
    visited = {start_x: 0}

    found_targets = {}

    while queue:
        curr, dist = queue.popleft()

        if curr in targets:
            if curr not in found_targets:
                found_targets[curr] = dist % 2
                if len(found_targets) == len(targets):
                    break

        # Neighbors in [0, 1)
        # 1. 1-x
        nx = 1 - curr
        if nx < 0: nx += 1
        if nx >= 1: nx -= 1
        if nx not in visited:
            visited[nx] = dist + 1
            queue.append((nx, dist + 1))

        # 2. {1/x}
        if curr != 0:
            nx = (1 / curr) % 1
            if nx not in visited:
                visited[nx] = dist + 1
                queue.append((nx, dist + 1))

        # 3. -x mod 1
        nx = (-curr) % 1
        if nx not in visited:
            visited[nx] = dist + 1
            queue.append((nx, dist + 1))

        if len(visited) > 100000:
            break

    for t in targets:
        if t in found_targets:
            print(f"{t}: {found_targets[t]}")
        else:
            print(f"{t}: Not found")

solve()

